package com.mfg.plm.service;
import com.mfg.common.api.ErrorCode;import com.mfg.common.exception.BizException;import com.mfg.security.config.CurrentUser;import com.mfg.workflow.dto.StartApprovalRequest;import com.mfg.workflow.entity.WfInstance;import com.mfg.workflow.service.ApprovalEngine;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.sql.Date;import java.util.*;
@Service @RequiredArgsConstructor public class EngineeringChangeChainService{private final JdbcTemplate jdbc;private final ApprovalEngine workflow;
 @Transactional(readOnly=true)public Page<Map<String,Object>> page(String type,String keyword,int page,int size){String table=switch(type){case"ecrs"->"plm_ecr";case"ecos"->"plm_eco";case"ecns"->"plm_ecn";default->throw invalid();},no=type.substring(0,3)+"_no",title=type.substring(0,3)+"_title";int p=Math.max(0,page-1),s=Math.min(200,Math.max(1,size));String w=keyword==null||keyword.isBlank()?"":" WHERE "+no+" LIKE ? OR "+title+" LIKE ?";Object[]a=w.isBlank()?new Object[]{}:new Object[]{"%"+keyword+"%","%"+keyword+"%"};Long t=jdbc.queryForObject("SELECT COUNT(*) FROM src_plm."+table+w,Long.class,a);List<Object>x=new ArrayList<>(Arrays.asList(a));x.add(s);x.add(p*s);return new PageImpl<>(jdbc.queryForList("SELECT * FROM src_plm."+table+w+" ORDER BY id DESC LIMIT ? OFFSET ?",x.toArray()),PageRequest.of(p,s),t==null?0:t);}
 @Transactional public Map<String,Object> createEcr(Map<String,Object>x){jdbc.update("INSERT INTO src_plm.plm_ecr(ecr_no,ecr_title,product_code,problem_desc,change_reason,urgency,proposal,planned_effective_date,created_by) VALUES(?,?,?,?,?,?,?,?,?)",req(x,"ecrNo"),req(x,"ecrTitle"),req(x,"productCode"),req(x,"problemDesc"),req(x,"changeReason"),value(x,"urgency","NORMAL"),text(x,"proposal"),date(x,"plannedEffectiveDate"),CurrentUser.usernameOrSystem());return latest("plm_ecr");}
 @Transactional public List<Map<String,Object>> impacts(Long id,List<Map<String,Object>> items){exists("plm_ecr",id);jdbc.update("DELETE FROM src_plm.plm_impact_analysis WHERE ecr_id=?",id);for(var x:items)jdbc.update("INSERT INTO src_plm.plm_impact_analysis(ecr_id,impact_type,object_code,impact_desc,risk_level,cost_impact,schedule_impact_days,owner_user) VALUES(?,?,?,?,?,?,?,?)",id,req(x,"impactType"),req(x,"objectCode"),text(x,"impactDesc"),value(x,"riskLevel","MEDIUM"),x.get("costImpact"),x.get("scheduleImpactDays"),text(x,"ownerUser"));jdbc.update("UPDATE src_plm.plm_ecr SET status='ANALYZED' WHERE id=?",id);return jdbc.queryForList("SELECT * FROM src_plm.plm_impact_analysis WHERE ecr_id=? ORDER BY id",id);}
 @Transactional public Map<String,Object> createEco(Long ecrId,Map<String,Object>x){Map<String,Object>ecr=one("plm_ecr",ecrId);if(!"ANALYZED".equals(String.valueOf(ecr.get("status"))))throw BizException.conflict("ECR必须先完成影响分析");jdbc.update("INSERT INTO src_plm.plm_eco(eco_no,ecr_id,eco_title,product_code,change_scope,target_type,target_code,new_version,created_by) VALUES(?,?,?,?,?,?,?,?,?)",req(x,"ecoNo"),ecrId,req(x,"ecoTitle"),ecr.get("product_code"),text(x,"changeScope"),req(x,"targetType"),text(x,"targetCode"),req(x,"newVersion"),CurrentUser.usernameOrSystem());jdbc.update("UPDATE src_plm.plm_ecr SET status='ECO_CREATED' WHERE id=?",ecrId);return latest("plm_eco");}
 @Transactional public WfInstance submitEco(Long id){Map<String,Object>e=one("plm_eco",id);if(!"DRAFT".equals(String.valueOf(e.get("status"))))throw BizException.conflict("只有草稿ECO可以提交");jdbc.update("UPDATE src_plm.plm_eco SET status='REVIEWING' WHERE id=?",id);return workflow.start(new StartApprovalRequest("ECO",id,String.valueOf(e.get("eco_no")),String.valueOf(e.get("eco_title")),"{\"targetType\":\""+e.get("target_type")+"\",\"targetCode\":\""+e.get("target_code")+"\"}"));}
 @Transactional public Map<String,Object> createEcnFromEco(Long ecoId){Map<String,Object>e=one("plm_eco",ecoId);if(!"APPROVED".equals(String.valueOf(e.get("status"))))throw BizException.conflict("ECO未批准");String no="ECN-"+String.format("%05d",ecoId);jdbc.update("INSERT INTO src_plm.plm_ecn(ecr_id,eco_id,ecn_no,ecn_title,product_code,bom_code,change_type,target_type,target_version,change_content,change_reason,ecn_status,submitted_by) SELECT ecr_id,id,?,?,product_code,IF(target_type='BOM',target_code,NULL),'DESIGN',target_type,new_version,change_scope,'ECO审批通过','APPROVED',? FROM src_plm.plm_eco WHERE id=? ON DUPLICATE KEY UPDATE eco_id=VALUES(eco_id)",no,e.get("eco_title"),CurrentUser.usernameOrSystem(),ecoId);return latest("plm_ecn");}
 @Transactional public Map<String,Object> implement(Long ecnId){Map<String,Object>e=one("plm_ecn",ecnId);if(!"APPROVED".equals(String.valueOf(e.get("ecn_status"))))throw BizException.conflict("ECN未批准");String type=String.valueOf(e.get("target_type")),target=String.valueOf(e.get("bom_code")),version=String.valueOf(e.get("target_version"));if("BOM".equals(type)){Map<String,Object>old=jdbc.queryForMap("SELECT * FROM src_mdm.md_bom WHERE bom_code=? ORDER BY id DESC LIMIT 1",target);jdbc.update("INSERT INTO src_mdm.md_bom(bom_code,bom_name,product_id,product_code,bom_version,bom_type,effective_date,is_current,base_qty,base_unit_code,status,version_no,change_reason,change_ecn_no,created_by) VALUES(?,?,?,?,?,?,CURDATE(),0,?,?, 'DRAFT',1,?,?,?)",target,old.get("bom_name"),old.get("product_id"),old.get("product_code"),version,old.get("bom_type"),old.get("base_qty"),old.get("base_unit_code"),e.get("change_reason"),e.get("ecn_no"),CurrentUser.usernameOrSystem());Long id=((Number)jdbc.queryForMap("SELECT LAST_INSERT_ID() id").get("id")).longValue();jdbc.update("INSERT INTO src_mdm.md_bom_line(bom_id,line_no,child_material_id,child_material_code,child_material_name,qty_per,unit_code,scrap_rate,seq_no,is_key_material,position_desc,substitute_group,remark) SELECT ?,line_no,child_material_id,child_material_code,child_material_name,qty_per,unit_code,scrap_rate,seq_no,is_key_material,position_desc,substitute_group,remark FROM src_mdm.md_bom_line WHERE bom_id=?",id,old.get("id"));}else if("ROUTING".equals(type)){Map<String,Object>old=jdbc.queryForMap("SELECT * FROM src_mdm.md_routing WHERE routing_code=? ORDER BY id DESC LIMIT 1",target);jdbc.update("INSERT INTO src_mdm.md_routing(routing_code,routing_name,product_code,routing_version,effective_date,is_current,status,version_no,change_reason,created_by) VALUES(?,?,?,?,CURDATE(),0,'DRAFT',1,?,?)",target,old.get("routing_name"),old.get("product_code"),version,e.get("change_reason"),CurrentUser.usernameOrSystem());Long id=((Number)jdbc.queryForMap("SELECT LAST_INSERT_ID() id").get("id")).longValue();jdbc.update("INSERT INTO src_mdm.md_routing_operation(routing_id,op_seq,operation_code,operation_name,work_center,setup_time_min,run_time_min,wait_time_min,default_equipment_code,required_skill,is_key_operation,is_inspection_op,inspection_required,remark) SELECT ?,op_seq,operation_code,operation_name,work_center,setup_time_min,run_time_min,wait_time_min,default_equipment_code,required_skill,is_key_operation,is_inspection_op,inspection_required,remark FROM src_mdm.md_routing_operation WHERE routing_id=?",id,old.get("id"));}else throw BizException.conflict("ECN目标类型必须为BOM或ROUTING");jdbc.update("UPDATE src_plm.plm_ecn SET ecn_status='IMPLEMENTED' WHERE id=?",ecnId);return one("plm_ecn",ecnId);}
 @Transactional public void approvedEco(Long id){jdbc.update("UPDATE src_plm.plm_eco SET status='APPROVED' WHERE id=?",id);createEcnFromEco(id);}@Transactional public void rejectedEco(Long id){jdbc.update("UPDATE src_plm.plm_eco SET status='REJECTED' WHERE id=?",id);}
 private Map<String,Object>one(String t,Long id){List<Map<String,Object>>r=jdbc.queryForList("SELECT * FROM src_plm."+t+" WHERE id=?",id);if(r.isEmpty())throw BizException.notFound("工程变更",id);return r.get(0);}private void exists(String t,Long id){one(t,id);}private Map<String,Object>latest(String t){return jdbc.queryForMap("SELECT * FROM src_plm."+t+" ORDER BY id DESC LIMIT 1");}private BizException invalid(){return BizException.of(ErrorCode.PARAM_INVALID,"未知工程变更类型");}private Object req(Map<String,Object>x,String k){Object v=x.get(k);if(v==null||String.valueOf(v).isBlank())throw BizException.of(ErrorCode.PARAM_INVALID,k+"不能为空");return v;}private String text(Map<String,Object>x,String k){Object v=x.get(k);return v==null||String.valueOf(v).isBlank()?null:String.valueOf(v);}private String value(Map<String,Object>x,String k,String d){String v=text(x,k);return v==null?d:v;}private Date date(Map<String,Object>x,String k){String v=text(x,k);return v==null?null:Date.valueOf(v);}}
